&lt;p&gt;&lt;span style=&quot;color: #000000;&quot;&gt;This position is open to the following preferred office locations:&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;color: #000000 !important;&quot;&gt;&lt;span style=&quot;color: #000000;&quot;&gt;San Francisco, CA&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #000000 !important;&quot;&gt;&lt;span style=&quot;color: #000000;&quot;&gt;Denver, CO&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;color: #000000 !important;&quot;&gt;&lt;span style=&quot;color: #000000;&quot;&gt;New York City, New York&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
